export function resolveGeneratedDictionaryAlias(value) {
  let current = String(value || '');
  const visited = new Set();
  while (DICTIONARY_ALIASES[current] && !visited.has(current)) {
    visited.add(current);
    current = DICTIONARY_ALIASES[current];
  }
  return current;
}
